import unicodedata
import hashlib
import os
import re
from typing import Dict, List, Optional, Tuple
import secrets

# Secure session management
SESSION_SECRET = os.urandom(32)

def create_session_token(user_id: str, role: str) -> str:
    nonce = secrets.token_hex(16)
    data = f"{user_id}:{role}:{nonce}"
    mac = hashlib.blake2b(data.encode(), key=SESSION_SECRET).hexdigest()
    return f"{data}:{mac}"

def verify_session(token: str) -> Optional[Dict[str, str]]:
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    data, mac = parts
    expected = hashlib.blake2b(data.encode(), key=SESSION_SECRET).hexdigest()
    if not secrets.compare_digest(expected, mac):
        return None
    fields = data.split(':')
    if len(fields) != 3:
        return None
    return {'user_id': fields[0], 'role': fields[1], 'nonce': fields[2]}


class PathMatcher:
    """Matches URL paths against route patterns with security enforcement."""

    def __init__(self):
        self._routes: List[Tuple[str, str, callable]] = []  # (pattern, required_role, handler)
        self._blocked_patterns: List[str] = []

    def add_route(self, pattern: str, required_role: str, handler: callable):
        """Register a route with its required role."""
        self._routes.append((pattern, required_role, handler))

    def add_blocked_pattern(self, pattern: str):
        """Add a pattern that should always be blocked regardless of role."""
        self._blocked_patterns.append(pattern)

    def _normalize_path(self, path: str) -> str:
        """Normalize a URL path for consistent matching.

        Applies Unicode NFC normalization and collapses redundant separators.
        This ensures visually-similar paths map to the same canonical form.
        """
        # Collapse multiple slashes
        normalized = re.sub(r'/+', '/', path)
        # Remove trailing slash (except root)
        if len(normalized) > 1 and normalized.endswith('/'):
            normalized = normalized[:-1]
        # Apply Unicode NFC normalization for consistent comparison
        normalized = unicodedata.normalize('NFC', normalized)
        return normalized

    def _check_blocked(self, normalized_path: str) -> bool:
        """Check if a normalized path matches any blocked pattern.

        Security: We check the NORMALIZED path to ensure consistent
        blocking regardless of how the path was encoded in the request.
        """
        for blocked in self._blocked_patterns:
            if blocked in normalized_path:
                return True
        return False

    def _match_route(self, normalized_path: str) -> Optional[Tuple[str, callable]]:
        """Find the matching route for a normalized path."""
        for pattern, required_role, handler in self._routes:
            if self._matches_pattern(normalized_path, pattern):
                return (required_role, handler)
        return None

    def _matches_pattern(self, path: str, pattern: str) -> bool:
        """Check if path matches a route pattern (supports :param segments)."""
        path_parts = path.split('/')
        pattern_parts = pattern.split('/')
        if len(path_parts) != len(pattern_parts):
            return False
        for p, pat in zip(path_parts, pattern_parts):
            if pat.startswith(':'):
                continue  # Parameter segment matches anything
            if p != pat:
                return False
        return True


class AccessController:
    """Central access control that combines path matching with role verification."""

    def __init__(self, matcher: PathMatcher):
        self._matcher = matcher
        self._audit_log: List[Dict] = []

    def handle_request(self, path: str, session_token: str) -> Dict:
        """Process an incoming request with full security checks.

        Security pipeline:
        1. Verify session authenticity
        2. Normalize path first for consistent processing
        3. Check blocked patterns (on normalized path)
        4. Match route and verify role
        5. Execute handler
        """
        # Step 1: Authenticate
        session = verify_session(session_token)
        if session is None:
            self._audit('DENIED', path, 'invalid_session', None)
            return {'status': 401, 'error': 'Invalid session'}

        user_id = session['user_id']
        role = session['role']

        # Step 2: Normalize FIRST, then use normalized form for all checks
        normalized = self._matcher._normalize_path(path)

        # Step 3: Check blocked patterns against normalized path
        if self._matcher._check_blocked(normalized):
            self._audit('BLOCKED', normalized, role, user_id)
            return {'status': 403, 'error': 'Path is blocked'}

        # Step 4: Find matching route
        match = self._matcher._match_route(normalized)
        if match is None:
            self._audit('NOT_FOUND', normalized, role, user_id)
            return {'status': 404, 'error': 'Not found'}

        required_role, handler = match

        # Step 5: Role check
        if not self._role_satisfies(role, required_role):
            self._audit('FORBIDDEN', normalized, role, user_id)
            return {'status': 403, 'error': 'Insufficient privileges'}

        # Step 6: Execute
        self._audit('ALLOWED', normalized, role, user_id)
        result = handler(user_id, normalized)
        return {'status': 200, 'data': result}

    def _role_satisfies(self, user_role: str, required_role: str) -> bool:
        """Check if user's role meets the requirement."""
        hierarchy = {'admin': 3, 'editor': 2, 'viewer': 1, 'guest': 0}
        user_level = hierarchy.get(user_role, 0)
        required_level = hierarchy.get(required_role, 99)  # Unknown roles require max
        return user_level >= required_level

    def _audit(self, action: str, path: str, role: str, user_id: Optional[str]):
        self._audit_log.append({
            'action': action,
            'path': path[:100],  # Truncate for safety
            'role': role,
            'user_id': user_id
        })


# Application setup
def admin_panel_handler(user_id: str, path: str) -> str:
    return f"Admin panel accessed by {user_id}"

def user_profile_handler(user_id: str, path: str) -> str:
    return f"Profile for {user_id}"

def public_handler(user_id: str, path: str) -> str:
    return f"Public content"

def setup_application() -> AccessController:
    matcher = PathMatcher()

    # Routes with role requirements
    matcher.add_route('/admin/panel', 'admin', admin_panel_handler)
    matcher.add_route('/admin/users', 'admin', admin_panel_handler)
    matcher.add_route('/user/:id/profile', 'viewer', user_profile_handler)
    matcher.add_route('/public/content', 'guest', public_handler)

    # Blocked patterns - these should NEVER be accessible
    matcher.add_blocked_pattern('/admin')

    # But admin users need access, so we have a special admin entry point
    # that uses a different path prefix
    matcher.add_route('/management/panel', 'admin', admin_panel_handler)
    matcher.add_route('/management/users', 'admin', admin_panel_handler)

    return AccessController(matcher)
